-- Queer Atlas: exactly four researched hotels for each city in the companion batch.
-- Idempotent and limited to the production-approved place type 'hotel'.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
 select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Aloft Providence Downtown","aliases":"Aloft Providence Downtown|Aloft Providence","city":"providence","description":"Modern riverfront hotel beside the Innovation District with W XYZ bar, social lobby and immediate access to PrideFest and the illuminated parade route.","vibe":"bright social hotel with explicit Rhode Island Pride positioning","tags":"social,cultural,mixed","hours":"Reception operates 24 hours; bar and fitness follow property schedules.","link":"https://www.marriott.com/en-us/hotels/pvdal-aloft-providence-downtown/overview/","location":"191 Dorrance Street, Providence, RI 02903, USA","lat":41.81862,"lng":-71.40836,"arrival":"Pride and WaterFire create street closures and lobby peaks; confirm parking and accessible-room configuration.","best":"Best for PrideFest, the river and a social contemporary base near downtown nightlife.","crowd":"LGBTQ+ Pride guests mix with business travellers, concert visitors and weekend groups.","dress":"Contemporary hotel casual; W XYZ becomes nightlife casual.","inclusion":"The hotel's official 2026 Rhode Island Pride page calls the property a Pride home base welcoming every identity and story.","basis":"Direct current first-party Pride campaign plus active Marriott property source.","class":"Select-service Aloft lifestyle hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://event.marriott.com/pvdal-aloft-providence-downtown/events/providence/rhode-island-pride","https://www.marriott.com/en-us/hotels/pvdal-aloft-providence-downtown/overview/"]},
 {"name":"The Beatrice","aliases":"The Beatrice|The Beatrice Hotel","city":"providence","description":"Boutique downtown hotel in the restored Exchange Building with Bellini restaurant and rooftop, positioned close to Snow Street nightlife and the rivers.","vibe":"polished independent boutique hotel with documented Pride advocacy","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; restaurant and rooftop use reservations and separate hours.","link":"https://www.thebeatrice.com/","location":"90 Westminster Street, Providence, RI 02903, USA","lat":41.82414,"lng":-71.41023,"arrival":"Rooftop and city events can crowd valet and elevators; reserve access and adapted-room needs.","best":"Best for couples wanting boutique service, rooftop drinks and short walks to the gay-bar cluster.","crowd":"LGBTQIA+ couples and Pride visitors mix with dining guests and design-focused travellers.","dress":"Polished city casual; Bellini rooftop leans smart-casual.","inclusion":"The hotel has marketed Pride packages and rooftop celebrations while documenting longstanding local LGBTQ+ advocacy.","basis":"Direct first-party hotel Pride and community-support evidence.","class":"Independent luxury boutique hotel","coords":"Exact official address checked 2026-08-27.","sources":["https://www.thebeatrice.com/press/","https://www.thebeatrice.com/"]},
 {"name":"Graduate by Hilton Providence","aliases":"Graduate by Hilton Providence|Graduate Providence|Providence Biltmore","city":"providence","description":"Landmark downtown hotel in the former Providence Biltmore with historic public rooms and immediate walking access to the arts, restaurants and queer nightlife.","vibe":"grand historic city hotel close to the compact queer circuit","tags":"cultural,luxury,mixed","hours":"Reception operates 24 hours; dining, fitness and event rooms vary.","link":"https://www.hilton.com/en/hotels/pvdgngu-graduate-providence/","location":"11 Dorrance Street, Providence, RI 02903, USA","lat":41.82438,"lng":-71.41263,"arrival":"Downtown event traffic affects valet and check-in; confirm historic-building accessibility and room type.","best":"Best for architecture and travellers wanting the most central base for Snow Street and Washington Street venues.","crowd":"Queer city-break guests mix with wedding groups, university visitors and heritage-hotel travellers.","dress":"City casual; events may be formal.","inclusion":"Included in current specialist LGBTQ-welcoming Providence accommodation guidance; no ownership claim is made.","basis":"Current LGBTQ travel inclusion catalogue paired with active first-party Hilton operation.","class":"Historic full-service Graduate by Hilton hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://www.travelgay.com/gay-providence-hotels/","https://www.hilton.com/en/hotels/pvdgngu-graduate-providence/"]},
 {"name":"The Dean Hotel","aliases":"The Dean Hotel|Dean Hotel Providence","city":"providence","description":"Compact design hotel in a converted downtown building with intimate rooms, coffee and bar concepts steps from Washington Street nightlife.","vibe":"independent urban boutique stay embedded in nightlife","tags":"cultural,social,cozy","hours":"Front desk schedule and late arrival instructions should be confirmed; outlets vary.","link":"https://thedeanhotel.com/","location":"122 Fountain Street, Providence, RI 02903, USA","lat":41.82208,"lng":-71.41663,"arrival":"Small rooms and an older building require advance confirmation of lifts, access and quiet-room position.","best":"Best for design-minded adults prioritising bars, theatres and a compact downtown stay.","crowd":"Queer couples and solo travellers mix with artists, performers and nightlife visitors.","dress":"Creative casual.","inclusion":"Actively included in current specialist LGBTQ-welcoming Providence hotel guidance.","basis":"Current LGBTQ travel inclusion listing plus live first-party hotel source.","class":"Independent design boutique hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://www.travelgay.com/gay-providence-hotels/","https://thedeanhotel.com/"]},

 {"name":"Hyatt Regency Sacramento","aliases":"Hyatt Regency Sacramento|Hyatt Regency Sacramento at Capitol Park","city":"sacramento","description":"Full-service hotel facing the State Capitol with outdoor pool, multiple dining options and a central position between Capitol Mall Pride and Lavender Heights.","vibe":"large civic hotel convenient to Pride, government and Midtown","tags":"luxury,mixed,social","hours":"Reception operates 24 hours; pool, dining and valet use separate schedules.","link":"https://www.hyatt.com/hyatt-regency/en-US/sacra-hyatt-regency-sacramento","location":"1209 L Street, Sacramento, CA 95814, USA","lat":38.57727,"lng":-121.49084,"arrival":"Capitol events and conventions produce driveway and elevator peaks; reserve parking and adapted rooms.","best":"Best for Pride weekend and travellers balancing Capitol Mall with a walk to Lavender Heights.","crowd":"LGBTQ+ festival guests mix with state-government, convention and leisure travellers.","dress":"Business or city casual.","inclusion":"Hyatt maintains global LGBTQ+ inclusion commitments; location places guests within Sacramento's documented queer core without implying local ownership.","basis":"Current corporate inclusion policy, official property source and destination LGBTQ geography.","class":"Upscale full-service Hyatt Regency","coords":"Exact official street address checked 2026-08-27.","sources":["https://www.hyatt.com/world-of-care/diversity-equity-inclusion","https://www.hyatt.com/hyatt-regency/en-US/sacra-hyatt-regency-sacramento","https://www.visitsacramento.com/plan/lgbtq/"]},
