 {"name":"Graduate by Hilton Richmond","aliases":"Graduate by Hilton Richmond|Graduate Richmond","city":"richmond","description":"VCU-area hotel with collegiate design, rooftop pool and walkable access to the Arts District, Godfrey's and central cultural venues.","vibe":"playful university hotel linking campus, arts and queer downtown","tags":"cultural,social,mixed","hours":"Reception operates 24 hours; rooftop and dining are seasonal or scheduled.","link":"https://www.hilton.com/en/hotels/ricgrgu-graduate-richmond/","location":"301 West Franklin Street, Richmond, VA 23220, USA","lat":37.54436,"lng":-77.44597,"arrival":"University and event weekends raise parking and elevator demand; confirm pool season and adapted rooms.","best":"Best for VCU visits and a walkable base between the Arts District and downtown queer venues.","crowd":"Queer students, alumni and couples mix with university families and city-break travellers.","dress":"Campus-inspired casual.","inclusion":"Hilton publishes explicit LGBTQ+ guest and workforce inclusion commitments; no local ownership claim.","basis":"Current corporate inclusion evidence paired with active first-party property details.","class":"Graduate by Hilton lifestyle hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://travel.hilton.com/en_us/articles/lgbtq-travel/","https://www.hilton.com/en/hotels/ricgrgu-graduate-richmond/"]},
 {"name":"Linden Row Inn","aliases":"Linden Row Inn|Linden Row","city":"richmond","description":"Historic boutique inn formed from restored row houses and a garden courtyard, close to the Arts District and downtown LGBTQ+ nightlife.","vibe":"romantic historic inn offering a quieter counterpoint to club hotels","tags":"cozy,cultural,relax","hours":"Reception and arrival service follow current property schedule; confirm late arrival.","link":"https://www.lindenrowinn.com/","location":"100 East Franklin Street, Richmond, VA 23219, USA","lat":37.54285,"lng":-77.44245,"arrival":"Historic stairs and varied room layouts require direct accessibility confirmation; parking is off-site or limited.","best":"Best for couples prioritising architecture, courtyard calm and downtown walkability.","crowd":"Queer couples and cultural travellers mix with wedding, heritage and business guests.","dress":"Relaxed smart-casual.","inclusion":"Selected as a lodging partner in inclusive Richmond visitor programmes; no queer ownership claim is made.","basis":"Active first-party operation plus official Richmond lodging-partner evidence and city LGBTQ context.","class":"Independent historic boutique inn","coords":"Exact official street address checked 2026-08-27.","sources":["https://www.lindenrowinn.com/","https://info.visitrichmondva.com/impactconference2025","https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/"]},

