 {"name":"Azur Hotel & Spa","aliases":"Azur Hotel & Spa|Azur Real Hotel Boutique|Azur Real Hotel","city":"cordoba","description":"Sixteen-room luxury boutique hotel in a restored 1915 house with candlelit underground water circuit, organic treatments and local gastronomy in the historic centre.","vibe":"intimate heritage luxury with exceptional spa privacy for couples","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; spa and restaurant require reservations.","link":"https://azurrealhotel.com/","location":"San Jerónimo 243, Córdoba, Argentina","lat":-31.41701,"lng":-64.18058,"arrival":"The small inventory and spa book quickly; confirm couple treatment, stairs and transfer arrangements directly.","best":"Best for couples wanting privacy, historic-centre access and serious wellness between late nights.","crowd":"LGBTQ+ couples mix with international luxury, wellness and gastronomy travellers.","dress":"Relaxed boutique luxury; spa attire in the circuit.","inclusion":"Selected as an inclusive central option based on personalised couple-focused hospitality and Argentina's established nondiscrimination framework; not claimed queer-owned.","basis":"Active first-party hotel data and official Córdoba tourism listing; inclusion claim kept deliberately limited.","class":"Independent luxury boutique spa hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://azurrealhotel.com/","https://turismo.cordoba.gob.ar/donde-dormir-cordoba-capital/"]},
 {"name":"Windsor Hotel & Tower","aliases":"Windsor Hotel & Tower|Windsor & Tower Hotel|Windsor Tower Hotel","city":"cordoba","description":"Four-star historic-centre hotel with Sibaris restaurant, rooftop heated pool, sauna, gym and personalised full-service operation near the Jesuit Block.","vibe":"classic full-service city hotel with rooftop relaxation","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; pool, spa, bars and restaurant have separate schedules.","link":"https://www.windsortower.com/","location":"Buenos Aires 214, Córdoba, Argentina","lat":-31.41808,"lng":-64.18330,"arrival":"Central traffic and events affect arrivals; confirm parking, adapted rooms and rooftop season before travel.","best":"Best for travellers wanting historic-centre walking, restaurant service and pool downtime.","crowd":"LGBTQ+ couples and visitors mix with business, heritage and domestic leisure guests.","dress":"Smart-casual in public rooms; relaxed at the pool.","inclusion":"Official city tourism emphasises personalised hospitality and accessible services; the hotel is not claimed queer-owned or queer-exclusive.","basis":"Active first-party hotel evidence and current municipal accommodation source, with conservative inclusion wording.","class":"Four-star independent full-service hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://turismo.cordoba.gob.ar/windsor-tower-hotel/","https://www.windsortower.com/"]},
 {"name":"Selina Nueva Córdoba","aliases":"Selina Nueva Córdoba|Selina Nueva Cordoba|Selina Córdoba","city":"cordoba","description":"Social accommodation in Nueva Córdoba with private and shared rooms, outdoor pool, cinema, café, library, cocktails and live programming near Güemes nightlife.","vibe":"young social stay bridging coworking, culture and late Nueva Córdoba","tags":"social,cultural,mixed","hours":"Reception and arrival schedule should be verified; pool, café and events vary.","link":"https://www.selina.com/argentina/nueva-cordoba/","location":"San Lorenzo 163, Córdoba, Argentina","lat":-31.42399,"lng":-64.18622,"arrival":"Shared-room, private-room and late-check-in conditions differ; confirm current operator status and accessibility before payment.","best":"Best for younger queer travellers wanting social space close to Europa, Güemes and city attractions.","crowd":"LGBTQ+ backpackers and remote workers mix with students, international travellers and local event audiences.","dress":"Informal hostel and pool casual.","inclusion":"Included as a social, mixed accommodation in the city's most visibly young queer-friendly district; no queer ownership claim.","basis":"Current municipal tourism listing and property operation, with inclusion based on district and mixed social format rather than unsupported certification.","class":"Lifestyle hostel and hotel hybrid","coords":"Exact municipal listing address checked 2026-08-27.","sources":["https://turismo.cordoba.gob.ar/selina/","https://www.selina.com/argentina/nueva-cordoba/"]},
 {"name":"NH Córdoba Panorama","aliases":"NH Córdoba Panorama|NH Cordoba Panorama|NH Panorama","city":"cordoba","description":"Central full-service hotel overlooking La Cañada with rooftop pool, gym, restaurant and direct access to X Bar, the historic centre and government district.","vibe":"practical international hotel beside La Cañada and central nightlife","tags":"mixed,relax,cultural","hours":"Reception operates 24 hours; pool, gym and dining follow separate schedules.","link":"https://www.nh-hotels.com/hotel/nh-cordoba-panorama","location":"Marcelo T. de Alvear 251, Córdoba, Argentina","lat":-31.41796,"lng":-64.19218,"arrival":"Central traffic and inflation-sensitive charges require confirming parking, taxes and room type before arrival.","best":"Best for reliable full-service facilities and walking access to La Cañada's queer-friendly bar circuit.","crowd":"LGBTQ+ couples and business travellers mix with tour groups and domestic city visitors.","dress":"General city-hotel casual.","inclusion":"Minor Hotels publishes diversity and nondiscrimination commitments; no local queer ownership claim.","basis":"Current corporate inclusion policy, active hotel source and verified position beside the queer-friendly La Cañada circuit.","class":"Four-star NH full-service city hotel","coords":"Exact official street address checked 2026-08-27.","sources":["https://www.minor.com/en/sustainability/diversity-and-inclusion","https://www.nh-hotels.com/hotel/nh-cordoba-panorama","https://cordobagay.com/lugares-gay-cordoba/"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (
 select h.*,string_to_array(h.tags,',')::text[] approved_tags,jsonb_build_object('queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,'coordinate_source',coords,'source_urls',sources,'research_status','current_inclusion_and_official_property_sources','updated_at','2026-08-27T00:00:00Z') intel from raw_hotels h
), updated as (
 update public.places p set name=h.name,type='hotel',description=h.description,vibe=h.vibe,vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from hotels h where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at)
select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now()) from hotels h where not exists(select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name));

select public.qa_refresh_city_seo_status(slug) from (values('providence'),('sacramento'),('richmond'),('dusseldorf'),('cordoba')) v(slug) where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select lower(trim(city)) city,count(*) filter(where type='hotel') batch_hotel_count,count(*) filter(where type='hotel')=4 target_exactly_four
from public.places
where lower(trim(city)) in('providence','sacramento','richmond','dusseldorf','cordoba')
  and lower(trim(name)) in(
    'aloft providence downtown','the beatrice','graduate by hilton providence','the dean hotel',
    'hyatt regency sacramento','hyatt centric downtown sacramento','kimpton sawyer hotel','inn off capitol park, ascend hotel collection',
    'quirk hotel richmond','moxy richmond downtown','graduate by hilton richmond','linden row inn',
    'hotel indigo düsseldorf - victoriaplatz','me and all hotel düsseldorf','25hours hotel das tour','ruby coco hotel düsseldorf',
    'azur hotel & spa','windsor hotel & tower','selina nueva córdoba','nh córdoba panorama'
  )
group by lower(trim(city)) order by lower(trim(city));
